<?php $categories=db()->query('SELECT * FROM categories ORDER BY brand,category_name')->fetchAll(); $product=$product??['name'=>'','brand'=>'Samsung','category_id'=>'','price'=>'','storage'=>'','condition'=>'New','quality'=>'','stock'=>0,'description'=>'','specifications'=>'']; ?>
<form class="admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div><label>Product name<input required name="name" value="<?=e($product['name'])?>"></label><label>Brand<select name="brand"><option <?= $product['brand']==='Samsung'?'selected':'' ?>>Samsung</option><option <?= $product['brand']==='Apple'?'selected':'' ?>>Apple</option></select></label></div><div><label>Category<select required name="category_id"><option value="">Select category</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?= $product['category_id']==$c['id']?'selected':'' ?>><?=e($c['brand'].' — '.$c['category_name'])?></option><?php endforeach ?></select></label><label>Price (KSh)<input required type="number" min="0" name="price" value="<?=e((string)$product['price'])?>"></label></div><div><label>Storage<input required name="storage" placeholder="e.g. 256GB" value="<?=e($product['storage'])?>"></label><label>Condition<select name="condition"><option <?= $product['condition']==='New'?'selected':'' ?>>New</option><option <?= $product['condition']==='Used'?'selected':'' ?>>Used</option></select></label><label>Stock quantity<input required type="number" min="0" name="stock" value="<?=e((string)$product['stock'])?>"></label></div><label>Available colours (comma separated)<input name="colors" value="<?=e(isset($product['id'])?implode(', ',colors_for((int)$product['id'])):'')?>" placeholder="Titanium Black, Blue"></label><label>Quality / condition description<input required name="quality" value="<?=e($product['quality'])?>" placeholder="e.g. Excellent, no scratches"></label><label>Product description<textarea required name="description"><?=e($product['description'])?></textarea></label><label>Technical specifications<textarea name="specifications"><?=e($product['specifications'])?></textarea></label><label>Product image (JPG, PNG, WEBP; max 5MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><button class="save" type="submit">Save product</button></form>
